/**
 * The sound files, generated by scripts/sfx/generate.js (`npm run sfx`) into assets/sfx/.
 * Keep the names in step with that script's SOUNDS table (a test checks it). Static
 * requires so Metro bundles every file; requiring an asset only yields its id or URI.
 */
export const SOUND_FILES = {
  'ui-tap': require('../../../assets/sfx/ui-tap.wav'),
  'ui-back': require('../../../assets/sfx/ui-back.wav'),
  tab: require('../../../assets/sfx/tab.wav'),
  buy: require('../../../assets/sfx/buy.wav'),
  deny: require('../../../assets/sfx/deny.wav'),
  'region-launch': require('../../../assets/sfx/region-launch.wav'),
  'datacentre-built': require('../../../assets/sfx/datacentre-built.wav'),
  'model-launch': require('../../../assets/sfx/model-launch.wav'),
  'event-open': require('../../../assets/sfx/event-open.wav'),
  'event-confirm': require('../../../assets/sfx/event-confirm.wav'),
  'moment-boost': require('../../../assets/sfx/moment-boost.wav'),
  'moment-averted': require('../../../assets/sfx/moment-averted.wav'),
  'rival-launch': require('../../../assets/sfx/rival-launch.wav'),
  'meter-warning': require('../../../assets/sfx/meter-warning.wav'),
  'win-sting': require('../../../assets/sfx/win-sting.wav'),
  'lose-sting': require('../../../assets/sfx/lose-sting.wav'),
  achievement: require('../../../assets/sfx/achievement.wav'),
  'garage-tap': require('../../../assets/sfx/garage-tap.wav'),
  'garage-buy': require('../../../assets/sfx/garage-buy.wav'),
  'garage-golden': require('../../../assets/sfx/garage-golden.wav'),
  'garage-ship': require('../../../assets/sfx/garage-ship.wav'),
  'garage-stage': require('../../../assets/sfx/garage-stage.wav'),
  'training-ready': require('../../../assets/sfx/training-ready.wav'),
  'training-reveal': require('../../../assets/sfx/training-reveal.wav'),
  'model-keep': require('../../../assets/sfx/model-keep.wav'),
  'model-scrap': require('../../../assets/sfx/model-scrap.wav'),
  'staff-move': require('../../../assets/sfx/staff-move.wav'),
  'happening-pop': require('../../../assets/sfx/happening-pop.wav'),
  'happening-miss': require('../../../assets/sfx/happening-miss.wav'),
  milestone: require('../../../assets/sfx/milestone.wav'),
  'shipday-reveal': require('../../../assets/sfx/shipday-reveal.wav'),
  'shipday-press': require('../../../assets/sfx/shipday-press.wav'),
  'bonus-multiply': require('../../../assets/sfx/bonus-multiply.wav'),
  'helper-tick': require('../../../assets/sfx/helper-tick.wav'),
} as const;

export type SoundName = keyof typeof SOUND_FILES;
export const SOUND_NAMES = Object.keys(SOUND_FILES) as SoundName[];

/** Per-sound playback: a base volume (files are all normalised to -6 dBFS) and how many overlapping voices it may use. */
export interface SoundSpec {
  volume: number;
  voices: number;
}

const DEFAULT_SPEC: SoundSpec = { volume: 0.8, voices: 1 };

/** Quiet, frequent sounds are turned down; stings and launches stay full. */
export const SOUND_SPECS: Partial<Record<SoundName, Partial<SoundSpec>>> = {
  'ui-tap': { volume: 0.45, voices: 2 },
  'ui-back': { volume: 0.5 },
  tab: { volume: 0.45 },
  deny: { volume: 0.6 },
  buy: { volume: 0.7, voices: 2 },
  'garage-tap': { volume: 0.4, voices: 3 },
  'garage-buy': { volume: 0.65, voices: 2 },
  'event-confirm': { volume: 0.7 },
  'moment-boost': { volume: 0.75, voices: 2 },
  'moment-averted': { volume: 0.75, voices: 2 },
  'win-sting': { volume: 0.9 },
  'lose-sting': { volume: 0.9 },
  'model-launch': { volume: 0.9 },
  // The Garage lab: soft and frequent ones down, the stage move full.
  'garage-stage': { volume: 0.9 },
  'training-ready': { volume: 0.55 },
  'training-reveal': { volume: 0.65 },
  'model-keep': { volume: 0.7 },
  'model-scrap': { volume: 0.6 },
  'staff-move': { volume: 0.4, voices: 2 },
  'happening-pop': { volume: 0.22 },
  'happening-miss': { volume: 0.35 },
  milestone: { volume: 0.7 },
  'shipday-reveal': { volume: 0.7 },
  'shipday-press': { volume: 0.75 },
  'bonus-multiply': { volume: 0.8 },
  'helper-tick': { volume: 0.12 },
};

export function soundSpec(name: SoundName): SoundSpec {
  return { ...DEFAULT_SPEC, ...SOUND_SPECS[name] };
}
